class FakeCollection:
    def __init__(self, db, name):
        self.db, self.name = db, name
    async def create_search_index(self, model):
        self.db.index_models[self.name] = model.document
    async def list_search_indexes(self, name):
        return FakeCursor([{'name': name, 'queryable': True}])
    async def bulk_write(self, operations, ordered):
        docs = self.db.docs.setdefault(self.name, {})
        for op in operations:
            doc = op._doc
            docs[doc['_id']] = doc
    async def delete_many(self, query):
        docs = self.db.docs.setdefault(self.name, {})
        for key in [k for k, v in docs.items() if v['document_id'] == query['document_id']]:
            del docs[key]
    async def drop(self):
        self.db.names.discard(self.name)
        self.db.docs.pop(self.name, None)
    async def aggregate(self, pipeline):
        self.db.pipelines.append(pipeline)
        docs = list(self.db.docs.get(self.name, {}).values())
        if '$vectorSearch' in pipeline[0]:
            return FakeCursor([{'document_id': d['document_id'], 'chunk': d['chunk'], 'score': 0.5} for d in docs])
        groups = {}
        for d in docs:
            g = groups.setdefault(d['document_id'], {'_id': d['document_id'], 'source': d['chunk']['source'],
                                                     'metadata': d['chunk']['metadata'], 'chunk_count': 0})
            g['chunk_count'] += 1
        return FakeCursor(groups.values())
