from agentscope.rag import MongoDBStore
async def go():
    store = MongoDBStore(uri='mongodb://x', database='rag')
    fake = FakeMongo()
    store._client = fake
    await store.create_collection('kb', dimensions=2)
    await store.insert('kb', [rec('d1', 0, [1.0, 0.0], 'a', {'tenant': 't1'}, 2), rec('d1', 1, [0.0, 1.0], 'b', {'tenant': 't1'}, 2),
                              rec('d2', 0, [1.0, 1.0], 'c', {'tenant': 't2'})])
    stored = sorted((d['document_id'], d['chunk']['chunk_index']) for d in fake.db.docs['kb'].values())
    hits = await store.search('kb', [1.0, 0.0], top_k=2, metadata_filter={'tenant': 't1', 'lang': 'en'})
    vs = fake.db.pipelines[-1][0]['$vectorSearch']
    def pairs(node, out):
        # The documented contract is an AND of chunk.metadata.<key> == value pairs; accept any equivalent
        # MongoDB spelling ($and of clauses, a flat document, {'$eq': v} or a bare value).
        for key, value in node.items():
            if key == '$and':
                for clause in value:
                    pairs(clause, out)
            else:
                out.append((key, value['$eq'] if isinstance(value, dict) and set(value) == {'$eq'} else value))
        return out
    docs = await store.list_documents('kb')
    await store.delete('kb', 'd1')
    after = await store.list_documents('kb')
    await store.delete_collection('kb')
    return [stored, sorted({h.document_id for h in hits}), vs['limit'], sorted(pairs(vs['filter'], [])),
            sorted((d.document_id, d.chunk_count, d.source) for d in docs), [d.document_id for d in after],
            await store.has_collection('kb')]
result = arun(go())
